begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=41.73657, parking_lng=-74.199091, parking_name='West Trapps parking lot off Route 44/55 (day-use fee, fills early)' where path <@ (select path from public.areas where id='ny_the_trapps') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 41.73657) / 2), 2) + cos(radians(41.73657)) * cos(radians(lat)) * power(sin(radians(lng - -74.199091) / 2), 2))) <= 4);
